# Strictly reconstructs a bounded allowlisted result; never exposes raw own/original output.
function Get-HtkkSafeGuiReferenceResult {
 [CmdletBinding()]
 param([Parameter(Mandatory=$true)][string]$ResultPath,[ValidateSet('inspect','profile-save','gtgt-inspect','gtgt-sheet-inspect','gtgt-annex12-inspect','gtgt-export-inspect','gtgt-roundtrip-inspect','gtgt-web-import-inspect')][string]$ExpectedMode)
 $invalid=[ordered]@{status='unavailable';mode=$ExpectedMode;stage='result-unavailable';runtimeRoundTrip=$false}
 try {
  if(-not(Test-Path -LiteralPath $ResultPath -PathType Leaf)){return $invalid}
  $file=Get-Item -LiteralPath $ResultPath
  if($file.Attributes -band [IO.FileAttributes]::ReparsePoint -or $file.Length -gt 16384 -or $file.Length -lt 2){$invalid.status='invalid';$invalid.stage='result-invalid';return $invalid}
  $value=Get-Content -LiteralPath $ResultPath -Raw -Encoding UTF8 | ConvertFrom-Json -AsHashtable
  $keys=@('format','mode','stage','failureCategory','editorKind','runtime','sourcePinsVerified','visibleForms','spreadCount','sheetRows','sheetColumns','mstBoxesMatched','initialRequiredTextBlank','editingApiAvailable','performedInputCount','originalSaveInvoked','savedHeaderExists','savedHeaderChecksMatched','savedHeaderCheckedFieldCount','saveDialogKind','savedHeaderMismatchMask','profileClosed','mainMenuObserved','d1MenuClicked','gtgtPeriodObserved','menuRowCount','menuClickCount','periodControlCount','periodControls','periodYearMonthMatched','periodFirstDeclarationMatched','periodActivityMatched','periodGeographyMatched','periodNoAnnexMatched','periodConfirmInvoked','gtgtWorkbookPinsVerified','gtgtMenuVersionMatched','gtgtPeriodModelMatched','gtgtSheetObserved','gtgtSheetNameMatched','gtgtDimensionsMatched','gtgtIdentityMatched','gtgtCt21Ready','gtgtCt21CaseMatched','gtgtCt21ConfirmationMatched','gtgtCt21LocksMatched','gtgtCt21BeforeExportMatched','gtgtCt21AfterImportMatched','gtgtCt21UncheckMatched','gtgtSignatureReady','gtgtMonetaryZero','periodAnnex12Matched','annex12SourcePinsMatched','annex12SheetObserved','annex12StructureMatched','annex12GroupMetadataMatched','annex12SttMatched','annex12LocksMatched','annex12SelectionActionCount','annex12SheetRows','annex12SheetColumns','annex12NumericCount','annex12NumericEmptyMask','annex12NumericNonzeroMask','annex12GroupCount','annex12FirstGroupId','annex12FirstGroupRows','annexSelectedCount','gtgtSheetRows','gtgtSheetColumns','gtgtSheetCount','gtgtEmptyMonetaryCount','exportCommandInvoked','exportSelectorMatched','exportButtonInvoked','exportDialogMatched','exportDestinationFresh','exportDialogSubmitted','exportFileExists','exportXmlRootMatched','exportSyntheticIdentityMatched','exportSuccessAcknowledged','exportSchemaPinnedVerified','exportFilenameKeyboardCommitted','exportFilenameParentKind','exportOriginalPathMatched','exportOriginalPathKind','exportScopedFileCount','exportScopedXmlCount','exportBytes','exportSha256','roundtripImportCommandInvoked','roundtripImportDialogMatched','roundtripImportKeyboardCommitted','roundtripImportDialogSubmitted','roundtripImportPathMatched','roundtripImportSheetMatched','roundtripImportSucceeded','roundtripReexportCommandInvoked','roundtripReexportSucceeded','roundtripXmlExactMatched','roundtripImportCheckedMoneyCount','roundtripReexportBytes','roundtripReexportSha256','gtgtCt42BeforeExportObserved','gtgtCt42LockedBeforeExport','gtgtCt42AfterImportObserved','gtgtCt42LockedAfterImport','gtgtAutoCalculationReady','gtgtBusinessInstanceMatched','gtgtCaseMoneyMatched','gtgtCt42Locked','webTaxValuesMatched','webCreationDateMatchedNativeBaseline','webServiceIdentityMatched','webInputVerified','webImportInputSha256','webSourceSha','webTaxLeafCount','webCaseId','webCaseEditCount','gtgtCaseMoneyCount','gtgtCaseMismatchMask','gtgtCaseNonzeroMask','controlKinds','realTaxpayerDataUsed','runtimeRoundTrip')
  if($value -isnot [Collections.IDictionary] -or $value.Count -ne $keys.Count){throw 'invalid'}
  foreach($key in $keys){if(@($value.Keys) -cnotcontains $key){throw 'invalid'}}
  foreach($key in @('format','mode','stage','failureCategory','editorKind','runtime','saveDialogKind')){if($value[$key] -isnot [string]){throw 'invalid'}}
  $stages=@('not-started','gtgt-annex12-inspected','source-or-runtime-not-matched','fixture-preexists','waiting-for-profile','initialization-unavailable','profile-wait-timeout','profile-controls-not-yet-unique','profile-dimensions-unmatched','fresh-synthetic-profile-not-established','profile-inspected','editing-api-unavailable','profile-province-code-unmatched','profile-ward-code-unmatched','profile-taxhead-code-unmatched','profile-taxlocal-code-unmatched','waiting-for-profile-save-permit','edit-name','edit-province','edit-ward','edit-address','edit-signer','edit-tax-authority-head','edit-tax-authority-local','original-save-invoking','success-modal-acknowledged','original-profile-saved-verified','original-profile-save-not-verified','profile-close-invoking','waiting-profile-close-ready','waiting-profile-close','gtgt-profile-owner-not-matched','waiting-main-menu','gtgt-profile-preconditions-not-matched','gtgt-menu-spread-not-yet-unique','gtgt-menu-id-not-unique','gtgt-menu-target-hidden','gtgt-menu-click-101','gtgt-menu-click-101_1','gtgt-menu-click-D1','waiting-gtgt-period','gtgt-period-inspected','gtgt-period-configuring','gtgt-period-province-selecting','gtgt-period-ward-selecting','gtgt-period-taxhead-selecting','gtgt-period-taxlocal-selecting','gtgt-period-activity-selecting','gtgt-period-inputs-not-matched','gtgt-period-confirm-invoking','waiting-gtgt-sheet','gtgt-sheet-inspected','gtgt-sheet-contract-not-matched','gtgt-export-command-invoking','gtgt-export-original-message-rejected','gtgt-export-file-dialog-waiting','gtgt-export-original-writing','gtgt-export-filename-keyboard-editing','gtgt-export-success-file-checking','gtgt-export-inspected','gtgt-import-ready-waiting','gtgt-import-file-dialog-waiting','gtgt-import-filename-keyboard-editing','gtgt-import-original-reading','gtgt-import-original-message-rejected','gtgt-import-success-sheet-checking','gtgt-reexport-ready-waiting','gtgt-reexport-command-invoking','gtgt-roundtrip-inspected','gtgt-web-input-checking','gtgt-web-import-ready-waiting','gtgt-web-import-inspected','gtgt-case-editing','gtgt-noactivity-checkbox-activating','gtgt-noactivity-confirming','gtgt-noactivity-checkbox-unchecking')
  if($value.format -cne 'htkk-gui-reference-automation-v1' -or $value.mode -cne $ExpectedMode -or $value.runtime -cne 'clr2-x86-custom-reference' -or $value.stage -cnotin $stages -or $value.failureCategory -cnotin @('none','reflection-invocation','operation-not-established','argument','com','io','other-standard') -or $value.saveDialogKind -cnotin @('not-observed','success-0002','invalid-0015','other-original-message') -or $value.editorKind -cnotin @('not-started','combo','text-box','other-control')){throw 'invalid'}
  foreach($key in @('periodAnnex12Matched','annex12SourcePinsMatched','annex12SheetObserved','annex12StructureMatched','annex12GroupMetadataMatched','annex12SttMatched','annex12LocksMatched','sourcePinsVerified','mstBoxesMatched','initialRequiredTextBlank','editingApiAvailable','originalSaveInvoked','savedHeaderExists','savedHeaderChecksMatched','profileClosed','mainMenuObserved','d1MenuClicked','gtgtPeriodObserved','periodYearMonthMatched','periodFirstDeclarationMatched','periodActivityMatched','periodGeographyMatched','periodNoAnnexMatched','periodConfirmInvoked','gtgtWorkbookPinsVerified','gtgtMenuVersionMatched','gtgtPeriodModelMatched','gtgtSheetObserved','gtgtSheetNameMatched','gtgtDimensionsMatched','gtgtIdentityMatched','gtgtCt21Ready','gtgtCt21CaseMatched','gtgtCt21ConfirmationMatched','gtgtCt21LocksMatched','gtgtCt21BeforeExportMatched','gtgtCt21AfterImportMatched','gtgtCt21UncheckMatched','gtgtSignatureReady','gtgtMonetaryZero','exportCommandInvoked','exportSelectorMatched','exportButtonInvoked','exportDialogMatched','exportDestinationFresh','exportDialogSubmitted','exportFileExists','exportXmlRootMatched','exportSyntheticIdentityMatched','exportSuccessAcknowledged','exportSchemaPinnedVerified','exportFilenameKeyboardCommitted','exportOriginalPathMatched','roundtripImportCommandInvoked','roundtripImportDialogMatched','roundtripImportKeyboardCommitted','roundtripImportDialogSubmitted','roundtripImportPathMatched','roundtripImportSheetMatched','roundtripImportSucceeded','roundtripReexportCommandInvoked','roundtripReexportSucceeded','roundtripXmlExactMatched','gtgtCt42BeforeExportObserved','gtgtCt42LockedBeforeExport','gtgtCt42AfterImportObserved','gtgtCt42LockedAfterImport','gtgtAutoCalculationReady','gtgtBusinessInstanceMatched','gtgtCaseMoneyMatched','gtgtCt42Locked','webTaxValuesMatched','webCreationDateMatchedNativeBaseline','webServiceIdentityMatched','webInputVerified','realTaxpayerDataUsed','runtimeRoundTrip')){if($value[$key] -isnot [bool]){throw 'invalid'}}
  if($value.realTaxpayerDataUsed -or $value.runtimeRoundTrip){throw 'invalid'}
  $maximum=@{annex12SelectionActionCount=1;annex12SheetRows=10000;annex12SheetColumns=512;annex12NumericCount=8;annex12NumericEmptyMask=255;annex12NumericNonzeroMask=255;annex12GroupCount=512;annex12FirstGroupId=10000;annex12FirstGroupRows=10000;gtgtCaseMismatchMask=134217727;gtgtCaseNonzeroMask=134217727;webCaseEditCount=3;gtgtCaseMoneyCount=27;webTaxLeafCount=70;visibleForms=64;spreadCount=512;sheetRows=10000;sheetColumns=10000;performedInputCount=7;savedHeaderCheckedFieldCount=8;savedHeaderMismatchMask=255;menuRowCount=2048;menuClickCount=3;periodControlCount=512;annexSelectedCount=512;gtgtSheetRows=10000;gtgtSheetColumns=10000;gtgtSheetCount=32;gtgtEmptyMonetaryCount=27;exportBytes=262144;exportScopedFileCount=32;exportScopedXmlCount=32;roundtripImportCheckedMoneyCount=27;roundtripReexportBytes=262144}
  foreach($key in $maximum.Keys){if(($value[$key] -isnot [int] -and $value[$key] -isnot [long]) -or $value[$key] -lt 0 -or $value[$key] -gt $maximum[$key]){throw 'invalid'}}
  if($value.exportSha256 -isnot [string] -or ($value.exportSha256 -cne '' -and $value.exportSha256 -cnotmatch '^[0-9a-f]{64}$')){throw 'invalid'}
  if($value.exportOriginalPathKind -isnot [string] -or $value.exportOriginalPathKind -cnotin @('not-observed','empty','expected-path','expected-double-extension','same-directory-other-name','other-directory')){throw 'invalid'}
  if($value.exportFilenameParentKind -isnot [string] -or $value.exportFilenameParentKind -cnotin @('not-observed','combobox','combobox-ex','other')){throw 'invalid'}
  if($value.roundtripReexportSha256 -isnot [string] -or ($value.roundtripReexportSha256 -cne '' -and $value.roundtripReexportSha256 -cnotmatch '^[0-9a-f]{64}$')){throw 'invalid'}
  foreach($entry in @(@{name='webImportInputSha256';length=64},@{name='webSourceSha';length=40})){if($value[$entry.name] -isnot [string] -or ($value[$entry.name] -cne '' -and $value[$entry.name] -cnotmatch ('^[0-9a-f]{'+$entry.length+'}$'))){throw 'invalid'}}
  if($value.webCaseId -isnot [string] -or $value.webCaseId -cnotin @('01GTGT-zero-M10-2026','01GTGT-sale10-M10-2026','01GTGT-sale10-half-M10-2026','01GTGT-sale10-manual-M10-2026','01GTGT-sale5-half-M10-2026','01GTGT-sale5-manual-M10-2026','01GTGT-noactivity-zero-M10-2026','01GTGT-noactivity-reset-sale10-M10-2026','01GTGT-noactivity-cancel-sale10-M10-2026','01GTGT-noactivity-uncheck-sale10-M10-2026','01GTGT-noactivity-keep-credit-M10-2026','01GTGT-zero-Q4-2026')){throw 'invalid'}
  if($value.webInputVerified -and ($value.webImportInputSha256.Length -ne 64 -or $value.webSourceSha.Length -ne 40)){throw 'invalid'}
  $kindKeys=@('form','button','combo','text','spread','other')
  if($value.controlKinds -isnot [Collections.IDictionary] -or $value.controlKinds.Count -ne $kindKeys.Count){throw 'invalid'}
  $safeKinds=[ordered]@{}
  foreach($key in $kindKeys){if(@($value.controlKinds.Keys) -cnotcontains $key -or ($value.controlKinds[$key] -isnot [int] -and $value.controlKinds[$key] -isnot [long]) -or $value.controlKinds[$key] -lt 0 -or $value.controlKinds[$key] -gt 512){throw 'invalid'};$safeKinds[$key]=[int]$value.controlKinds[$key]}
  $allowedPeriodNames=@('chkTkhaiThang','chkTKQuy','OptTKThang','OptChinhthuc','OptBosung','mskYear','mskMonth','cbbQuy','btnDongY','cmdClose','axfpsPhuLuc','cboNganhKD','chkChonPhuLucKeKhaiAll','cboCQTCuc','cboCQTChiCuc','cboTinh','cboXa')
  if($value.periodControls -isnot [Collections.IDictionary] -or $value.periodControls.Count -gt $allowedPeriodNames.Count){throw 'invalid'}
  $safePeriod=[ordered]@{}
  foreach($name in $value.periodControls.Keys){
   if($name -isnot [string] -or $name -cnotin $allowedPeriodNames){throw 'invalid'}
   $description=$value.periodControls[$name];$descriptionKeys=@('kind','visible','enabled','checkedAvailable','checked')
   if($description -isnot [Collections.IDictionary] -or $description.Count -ne 5){throw 'invalid'}
   foreach($key in $descriptionKeys){if(@($description.Keys) -cnotcontains $key){throw 'invalid'}}
   if($description.kind -isnot [string] -or $description.kind -cnotin @('spread','radio','check','masked-text','text','combo','button','other')){throw 'invalid'}
   foreach($key in @('visible','enabled','checkedAvailable','checked')){if($description[$key] -isnot [bool]){throw 'invalid'}}
   if($description.checkedAvailable -ne ($description.kind -in @('radio','check')) -or (-not $description.checkedAvailable -and $description.checked)){throw 'invalid'}
   $safePeriod[$name]=[ordered]@{kind=$description.kind;visible=$description.visible;enabled=$description.enabled;checkedAvailable=$description.checkedAvailable;checked=$description.checked}
  }
  $safe=[ordered]@{status='valid'}
  foreach($key in $keys){if($key -eq 'controlKinds'){$safe[$key]=$safeKinds}elseif($key -eq 'periodControls'){$safe[$key]=$safePeriod}else{$safe[$key]=$value[$key]}}
  return $safe
 }catch{$invalid.status='invalid';$invalid.stage='result-invalid';return $invalid}
}
